  waveGrad(vXZ, vec2(uWindDir.x * 0.9 - uWindDir.y * 0.42, uWindDir.x * 0.42 + uWindDir.y * 0.9), 27.0 * ws, 0.26 * ws, footprint, grad, jacobian);
